# Studyo 0.5.56 yamasi: Google'in kapattigi Gemini modeli (404 "no longer available to new users") kalici olarak atlanir,
# siradaki Flash-Lite modeline gecilir; hepsi doluysa denetim hata vermez, ertesi gun surer. 0.5.55 uzerine.
# Kod klasorunde: python3 studyo_0556_yama.py. Tekrar calistirilabilir.
import base64, hashlib, os, sys, zlib
D = [
    ('kutuphane/yz.py', '0884fcd3daf708ca2fe518d3cda1c066', '3f1f135835141bcf976b45f05fd6d2ef',
     ''),
    ('kutuphane/main.py', 'b205e30829f3f574b28169b354555230', 'cb39f583490168d0944adb1a37449717',
     ''),
    ('tests/test_0556.py', None, 'f9de84f85d63bafe7757c693f793a9b9',
     ''),
]
md5 = lambda p: hashlib.md5(open(p, 'rb').read()).hexdigest() if os.path.exists(p) else None
for yol, eski, yeni, _ in D:
    m = md5(yol)
    if m not in (eski, yeni):
        print('HATA:', yol, 'beklenmeyen icerik (md5', m, ') - hicbir dosya degistirilmedi'); sys.exit(1)
for yol, eski, yeni, veri in D:
    if md5(yol) == yeni:
        print('ATLANDI (zaten yeni):', yol); continue
    icerik = zlib.decompress(base64.b64decode(veri))
    assert hashlib.md5(icerik).hexdigest() == yeni
    os.makedirs(os.path.dirname(yol) or '.', exist_ok=True)
    open(yol, 'wb').write(icerik)
    print('YAZILDI:', yol, yeni)
print('TAMAM')
